// 本片数字由 scratchpad/v11.py 与 v11b.py 独立核算，逐条列在这里备查：
// Σ_{t≥1} t^(-2) = π²/6 = 1.644934 < 2（部分和 1.549768 / 1.634984 / 1.644834 / 1.644933）
// 置信半径由 exp(-2nu²) = δ/t² 反解：u = sqrt( log(t²/δ) / (2n) )，已数值回代验证
// Σ_{n=1}^{N} 1/√n ≤ 2√N（N=100 时 18.5896 vs 20；N=10000 时 198.5446 vs 200）
// Σ_a √N_a 在 ΣN_a=T 下均分时最大：T=10000,m=5 -> 223.61 = √(mT)，一臂独大只有 103.98
// 40 次重复、臂 (0.5,0.45,0.4) 的每千步遗憾：
//   ε-贪心(ε=0.1)  6.588 / 5.318 / 5.070 / 5.034  -> 停在理论值 ε/m·ΣΔ = 5.00
//   UCB            12.981 / 4.538 / 1.588 / 0.724 -> 继续下降
// 贪心锁死在次优臂：899/2000 = 45.0%（T=3000）
function ucbU(n,t,d){return Math.sqrt(Math.log(t*t/d)/(2*n));}
function basel(N){var s=0,t;for(t=1;t<=N;t++)s+=1/(t*t);return s;}
function gapSum(arms){var b=Math.max.apply(null,arms),s=0,i;for(i=0;i<arms.length;i++)s+=b-arms[i];return s;}

